sys_script_include.script:
var discordNotification = Class.create();

discordNotification.prototype = {

    initialize: function() {
        this.webhookUrl = gs.getProperty(
            'x_1209398_wrm.discord.webhook_url'
        );
    },

    sendMessage: function(message, emoji) {

        // Default emoji if none is provided
        emoji = emoji || '🚨';

        if (gs.nil(this.webhookUrl)) {
            gs.error(
                'Discord notification failed: ' +
                'Webhook URL system property is empty.'
            );
            return false;
        }

        try {

            var payload = {
                content: emoji + ' ' + message
            };

            var request = new sn_ws.RESTMessageV2();

            request.setEndpoint(this.webhookUrl);
            request.setHttpMethod('POST');
            request.setRequestHeader(
                'Content-Type',
                'application/json'
            );
            request.setRequestBody(
                JSON.stringify(payload)
            );

            var response = request.execute();
            var statusCode = response.getStatusCode();

            gs.info(
                'Discord notification sent. Status: ' +
                statusCode
            );

            return statusCode >= 200 && statusCode < 300;

        } catch (ex) {

            gs.error(
                'Discord notification failed: ' +
                ex.message
            );

            return false;
        }
    },

    type: 'discordNotification'
};
